const input = $input.first().json ?? {};
const isId = (value) => typeof value === 'string' && value.length >= 1 && value.length <= 64;
const messages = {
  invalid_handoff_event: 'No se pudo validar el evento de derivación.',
  notification_rate_limited: 'El canal de avisos limitó temporalmente la solicitud.',
  notification_rejected: 'El canal de avisos rechazó la solicitud.',
  notification_unavailable: 'El canal de avisos no está disponible temporalmente.',
  notification_ledger_unavailable: 'No se pudo confirmar la idempotencia del aviso.',
  handoff_action_auth_rejected: 'VantixApp rechazó la autenticación del aviso de derivación.',
  handoff_action_not_found: 'No se encontró el evento de derivación solicitado.',
  handoff_action_conflict: 'El evento de derivación cambió de estado.',
  handoff_action_rate_limited: 'El aviso de derivación fue limitado temporalmente.',
  handoff_action_rejected: 'VantixApp rechazó el aviso de derivación.',
  handoff_action_unavailable: 'No se pudo enviar el aviso de derivación.',
  invalid_followup_event: 'No se pudo validar el evento de seguimiento.',
  invalid_action_response: 'La acción de seguimiento devolvió una respuesta no válida.',
  action_auth_rejected: 'VantixApp rechazó la autenticación de la acción.',
  action_not_found: 'No se encontró el evento de seguimiento solicitado.',
  action_conflict: 'El evento de seguimiento cambió de estado.',
  action_rate_limited: 'La acción de seguimiento fue limitada temporalmente.',
  action_rejected: 'VantixApp rechazó la acción de seguimiento.',
  action_unavailable: 'La acción de seguimiento no está disponible temporalmente.',
  unknown_workflow_error: 'La automatización no pudo completarse.',
};
const requestedCode = typeof input.errorCode === 'string' ? input.errorCode : 'unknown_workflow_error';
const errorCode = Object.prototype.hasOwnProperty.call(messages, requestedCode) ? requestedCode : 'unknown_workflow_error';
const errorContext = ['router', 'handoff', 'followup'].includes(input.errorContext) ? input.errorContext : 'router';
const shouldCallback = isId(input.eventId) && isId(input.organizationId) && isId(input.runId);
if (!shouldCallback) return [{ json: { shouldCallback: false } }];
const callbackTimestamp = Date.now();
const callbackBody = JSON.stringify({
  eventId: input.eventId,
  organizationId: input.organizationId,
  runId: input.runId,
  timestamp: callbackTimestamp,
  status: 'failed',
  externalExecutionId: String($execution.id),
  errorCode,
  errorMessage: messages[errorCode],
  responseMeta: { workflow: 'vantix-error-handler', source: errorContext },
});
return [{ json: { shouldCallback: true, callbackBody, callbackTimestamp: String(callbackTimestamp) } }];
